-- ====================================================================
-- SejarahWira  |  ERA 5: Agama dan Kepercayaan  |  seed_era5.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) tujuh agama dan ajaran, (2) rumah ibadat, (3) kedudukan Islam
-- dalam Perlembagaan (Perkara 3), (4) kepercayaan Orang Asli (Mah Meri, Temiar, Semai), (5) kepercayaan Iban dan Kadazandusun,
-- (6) kepercayaan Bisaya dan Bajau. Naratif hanya berbeza pada peranan, suara, watak sampingan dan jenis cabaran.
--
-- Pelajar MERASUK jasad watak rekaan (peranan naratif):
--   Naratif 1 (Nota Lapangan Tujuh Pintu)         = Pengkaji Budaya (NPC 81)
--   Naratif 2 (Persidangan Para Penjaga Adat)     = Bobohizan Penjaga Padi (NPC 82)
--   Naratif 3 (Syair Seribu Kepercayaan)          = Lemambang Penyair (NPC 83)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (tiada NPC sedia ada diperlukan; NPC 81-98 dibuat di sini):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era5.sql
-- Selamat dijalankan berulang kali (kandungan Era 5 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA: Perkara 3(2) ditulis sebagai 'di negeri yang mempunyai Raja, Raja ialah Ketua Agama Islam' (bahan asal ayatnya tidak jelas).
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 5 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 5;

-- 2. NPC baharu Era 5 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 5 (50 soalan aneka pilihan, ID 501-550)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 5;


COMMIT;