INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(81, 'Pengkaji Budaya', 'Pengkaji yang mengembara dengan buku nota lapangan untuk mengenali agama dan kepercayaan rakyat Malaysia.', 'Mencatat agama dan kepercayaan dengan adil dan hormat supaya semua kaum saling memahami.', 'ahli_antropologi_UNESCO.png'),
(82, 'Bobohizan Penjaga Padi', 'Bobohizan yang menjaga upacara semangat padi dan memimpin para penjaga adat (watak rekaan).', 'Menurunkan cerita kepercayaan setiap kaum kepada generasi muda dengan penuh hormat.', 'bobohizan.png'),
(83, 'Lemambang Penyair', 'Lemambang yang membaca jampi mentera dan melagukan puji-pujian kepada Petara (watak rekaan).', 'Menjaga syair dan upacara supaya kepercayaan setiap kaum difahami dan dihormati.', 'lemambang.png'),
(84, 'Aishah', 'Gadis Muslim yang peramah dan petah bertanya (watak rekaan).', 'Mewakili penganut Islam dalam perbualan antara agama.', 'gadis_melayu.png'),
(85, 'Daniel', 'Pemuda Kristian dari Sarawak yang mesra dan suka bergurau (watak rekaan).', 'Mewakili penganut Kristian dalam perbualan antara agama.', 'orang_sarawak.png'),
(86, 'Mei Ling', 'Gadis Buddha yang lembut tetapi bijak berjenaka (watak rekaan).', 'Mewakili penganut Buddha dalam perbualan antara agama.', 'amoi_cina.png'),
(87, 'Kavitha', 'Gadis Hindu yang ceria dan gemar bercerita (watak rekaan).', 'Mewakili penganut Hindu dalam perbualan antara agama.', 'gadis_india.png'),
(88, 'Harjit', 'Pemuda Sikh yang tenang dan ramah (watak rekaan).', 'Mewakili penganut Sikh dalam perbualan antara agama.', 'jejaka_india.png'),
(89, 'Kenny', 'Pemuda yang mengamalkan Ajaran Tao dan Ajaran Konfusius, suka bergurau (watak rekaan).', 'Mewakili penganut Ajaran Tao dan Ajaran Konfusius dalam perbualan antara agama.', 'lengchai_cina.png'),
(90, 'Tok Batin Temiar', 'Orang tua Orang Asli suku Temiar yang tenang dan bijaksana (watak rekaan).', 'Mewakili kepercayaan Orang Asli suku Temiar dan Semai di Semenanjung.', 'orang_tradisi_lama.png'),
(91, 'Pak Mah Meri', 'Lelaki suku Mah Meri yang ramah dan pandai berseloroh (watak rekaan).', 'Mewakili suku Mah Meri dan upacara Puja Pantai.', 'mah_meri.png'),
(92, 'Apai Jelani', 'Orang tua Iban yang mesra dan pandai bercerita (watak rekaan).', 'Mewakili masyarakat Iban dan upacara Miring.', 'sarawakian.png'),
(93, 'Linda', 'Gadis Kadazandusun yang bersemangat dan petah bercerita (watak rekaan).', 'Mewakili masyarakat Kadazandusun dan Kinorohingan.', 'gadis_sabah.png'),
(94, 'Pak Tani Bisaya', 'Petani Bisaya di Sarawak yang peramah dan rajin (watak rekaan).', 'Mewakili masyarakat Bisaya dan upacara Tamarok.', 'petani.png'),
(95, 'Pak Bajau', 'Lelaki Bajau dari Sabah yang peramah dan suka menjamu tetamu (watak rekaan).', 'Mewakili masyarakat Bajau dengan upacara Ngeduang dan Mag''ombo.', 'orang_bajau.png'),
(96, 'Tuanku Sultan', 'Ketua negeri bergelar Sultan yang juga Ketua Agama Islam di negerinya (watak rekaan).', 'Menerangkan kedudukan Raja sebagai Ketua Agama Islam di negeri beraja.', 'sultan.png'),
(97, 'Yang di-Pertua Negeri', 'Ketua negeri yang dilantik, dari negeri tanpa Raja (watak rekaan).', 'Menerangkan kedudukan Yang di-Pertuan Agong sebagai Ketua Agama Islam di Melaka, Pulau Pinang, Sabah dan Sarawak.', 'yang_dipertuan_negeri.png'),
(98, 'Murid Sekolah', 'Murid yang gemar bertanya dan sentiasa ingin tahu (watak rekaan).', 'Mewakili generasi muda yang belajar menghormati agama dan kepercayaan lain.', 'budak_gajet.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(501, 'Nota Lapangan Tujuh Pintu', 5, 'Masuki peranan seorang pengkaji budaya dengan buku nota lapangan. Dalam setiap misi kau mengenali tujuh agama dan ajaran, rumah ibadat mereka, kedudukan Islam dalam Perlembagaan, serta kepercayaan Orang Asli, Iban, Kadazandusun, Bisaya dan Bajau.'),
(502, 'Persidangan Para Penjaga Adat', 5, 'Masuki peranan Bobohizan yang dijemput ke persidangan para penjaga adat. Sambil mendengar wakil setiap agama, kau belajar tentang tujuh agama dan ajaran, rumah ibadat, Perkara 3 Perlembagaan, serta kepercayaan Orang Asli, Iban, Kadazandusun, Bisaya dan Bajau.'),
(503, 'Syair Seribu Kepercayaan', 5, 'Masuki peranan Lemambang yang melagukan syair di Pesta Kepercayaan Sekolah. Dalam setiap bait kau mengenali tujuh agama dan ajaran, rumah ibadat, Perkara 3 Perlembagaan, serta kepercayaan Orang Asli, Iban, Kadazandusun, Bisaya dan Bajau.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e5_n1_s1', 'Taman Tujuh Pintu pada waktu senja. Kau, pengkaji budaya, melangkah masuk dengan buku nota lapangan, dan wakil setiap agama sudah menunggu di pintu masing-masing.', 1, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s2', 'Laluan batu di antara rumah-rumah ibadat yang berdiri berdekatan. Kau, pengkaji budaya, menggenggam pena sambil mencari rumah ibadat setiap agama untuk dicatat.', 2, 501, 'tempat_beribadat_berdekat.png'),
('e5_n1_s3', 'Dewan Perlembagaan yang sunyi tetapi penuh wibawa. Kau, pengkaji budaya, membuka lampiran Perkara 3 dan mendengar penerangan daripada para ketua negeri.', 3, 501, 'bangunan_perlembagaan.png'),
('e5_n1_s4', 'Pantai kampung Mah Meri yang riuh dengan upacara. Kau, pengkaji budaya, membuka buku nota di tepi persisiran dan mendengar suku Mah Meri, Temiar dan Semai bercerita.', 4, 501, 'mah_meri_puja_pantai.png'),
('e5_n1_s5', 'Tepi sungai dan pokok besar yang menjadi saksi upacara. Kau, pengkaji budaya, mencatat kepercayaan masyarakat Iban dan Kadazandusun dengan teliti.', 5, 501, 'upacara_miring.png'),
('e5_n1_s6', 'Ladang baharu yang sedang dibuka di pinggir hutan. Kau, pengkaji budaya, mencatat kepercayaan masyarakat Bisaya dan Bajau sambil angin membawa bau tanah dan asap.', 6, 501, 'tamarok_bisaya.png'),
('e5_n2_s1', 'Laluan batu berlampu lilin di antara rumah-rumah ibadat pada waktu petang. Kau, Bobohizan, melangkah masuk ke persidangan sambil membawa loceng kecil, dan wakil setiap agama mengangguk hormat.', 1, 502, 'tempat_beribadat_berdekat.png'),
('e5_n2_s2', 'Taman rumah ibadat yang luas di antara bukit dan bandar. Kau, Bobohizan, memandang dari atas bukit dan mencari rumah ibadat setiap agama yang berderet di bawah.', 2, 502, 'tempat_beribadat_semua.png'),
('e5_n2_s3', 'Dewan Perlembagaan berlantai marmar. Kau, Bobohizan, duduk di antara Sultan dan Yang di-Pertua Negeri sambil mendengar penerangan Perkara 3.', 3, 502, 'bangunan_perlembagaan.png'),
('e5_n2_s4', 'Pantai Mah Meri dengan bau garam dan asap kemenyan nipis. Kau, Bobohizan, duduk bersila di atas tikar bersama Pak Mah Meri dan Tok Batin Temiar sambil ombak berbisik.', 4, 502, 'mah_meri_puja_pantai.png'),
('e5_n2_s5', 'Sawah padi menguning ketika matahari terbit. Kau, Bobohizan, berdiri di batas sawah bersama penari Kadazandusun sambil Apai Jelani dari Iban datang bertamu.', 5, 502, 'kinorohingan.png'),
('e5_n2_s6', 'Beranda rumah kayu yang riuh dengan jamuan. Kau, Bobohizan, duduk bersila bersama Pak Bajau dan petani Bisaya sambil dulang kuih dan nasi dihulur dari tangan ke tangan.', 6, 502, 'ngeduang.png'),
('e5_n3_s1', 'Pesta Kepercayaan Sekolah di padang yang berlatar bukit dan bandar. Kau, Lemambang, melangkah dengan pakaian adat sambil murid-murid bersorak dan papan tanda besar tersergam di hadapan.', 1, 503, 'tempat_beribadat_semua.png'),
('e5_n3_s2', 'Laluan batu yang menghubungkan rumah-rumah ibadat. Kau, Lemambang, berjalan perlahan dengan syair di bibir sambil murid-murid menjinjing kad nama rumah ibadat.', 2, 503, 'tempat_beribadat_berdekat.png'),
('e5_n3_s3', 'Dewan Perlembagaan yang sejuk dan tenang. Kau, Lemambang, berdiri di hadapan lembaran Perkara 3 sambil Tuanku Sultan dan Yang di-Pertua Negeri menunggu di sisi.', 3, 503, 'bangunan_perlembagaan.png'),
('e5_n3_s4', 'Pantai Mah Meri pada waktu pagi. Kau, Lemambang, mengalunkan syair perlahan sambil Pak Mah Meri dan Tok Batin Temiar duduk bersila di atas tikar.', 4, 503, 'mah_meri_puja_pantai.png'),
('e5_n3_s5', 'Pokok besar di tebing sungai dan awan syair beralun di langit. Kau, Lemambang, berdiri bersama Linda dari Kadazandusun sambil Apai Jelani dari Iban tersenyum bangga.', 5, 503, 'upacara_miring.png'),
('e5_n3_s6', 'Pantai Semporna yang berhias kain berwarna dan perahu berbendera. Kau, Lemambang, berjalan di atas tikar anyaman sambil Pak Bajau dan petani Bisaya datang menyambut.', 6, 503, 'upacara_pantai.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(501, 'e5_n1_s1', 'Misi Kenal Tujuh Wakil', 'Bantu murid menyenaraikan semua agama dan ajaran yang diwakili di Taman Tujuh Pintu.', '3', 'Mengenal pasti agama dan kepercayaan utama di Malaysia.', '{"prompt": "Seorang murid menahan kau dan bertanya: yang manakah senarai lengkap agama dan ajaran di Taman Tujuh Pintu?", "options": [{"text": "Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.", "isCorrect": true}, {"text": "Islam, Kristian, Buddha, Hindu dan Sikh sahaja, tanpa Ajaran Tao dan Ajaran Konfusius.", "isCorrect": false, "consequence": "Murid itu mencatat lima sahaja. Kenny terkilan kerana dua ajarannya tidak disebut dan dilupakan."}, {"text": "Islam, Kristian, Buddha, Hindu, Ajaran Tao dan Ajaran Konfusius, tanpa Sikh.", "isCorrect": false, "consequence": "Murid itu mencatat enam sahaja. Harjit terdiam kerana agamanya tertinggal daripada senarai."}], "aftermath": "Senarai agama tidak lengkap. Murid-murid pulang dengan nota yang meninggalkan beberapa agama.", "turns": [{"after": 6, "options": [{"text": "Ajaran Tao dan Ajaran Konfusius.", "isCorrect": true, "reaction": "Tepat, pengkaji! Kenny menepuk dada dan semua wakil bertepuk tangan. Satu mata untuk kau!"}, {"text": "Agama Buddha dan agama Hindu.", "isCorrect": false, "reaction": "Itu wakil Mei Ling dan Kavitha, pengkaji! Kenny ketawa dan menunjuk ke pintunya sendiri."}, {"text": "Agama Islam dan agama Kristian.", "isCorrect": false, "reaction": "Itu wakil Aishah dan Daniel! Kenny menggeleng-geleng sambil tersenyum."}], "clue": "Kenny menyebut dua ajaran itu pada akhir senarai, selepas Sikh."}]}'),
(502, 'e5_n1_s2', 'Misi Kamera: Rumah Ibadat', 'Cari rumah ibadat bagi lima kumpulan agama pada gambar dan kenal pasti namanya.', '2', 'Mengenal pasti rumah ibadat pelbagai agama di Malaysia.', '{"bgImage": "../assets/gameAsset/background/tempat_beribadat_berdekat.png", "hotspots": [{"name": "Masjid: rumah ibadat bagi penganut Islam", "top": "40%", "left": "10%"}, {"name": "Gereja: rumah ibadat bagi penganut Kristian", "top": "30%", "left": "33%"}, {"name": "Tokong: rumah ibadat Konfusius dan Tao, juga Buddha", "top": "55%", "left": "51%"}, {"name": "Wat atau tokong: rumah ibadat bagi penganut Buddha", "top": "45%", "left": "62%"}, {"name": "Kuil: rumah ibadat bagi penganut Hindu", "top": "45%", "left": "70%"}, {"name": "Gurdwara: rumah ibadat bagi penganut Sikh", "top": "30%", "left": "90%"}], "aftermath": "Rumah ibadat tersalah catat. Murid-murid pulang dengan gambar yang berlabel salah.", "turns": [{"after": 6, "options": [{"text": "Gurdwara Sikh.", "isCorrect": true, "reaction": "Tepat, pengkaji! Murid itu menjerit gembira dan mengambil gambar gurdwara itu."}, {"text": "Gereja Kristian.", "isCorrect": false, "reaction": "Gereja itu milik Kristian, pengkaji! Daniel melambai dari menaranya dan ketawa."}, {"text": "Kuil Hindu.", "isCorrect": false, "reaction": "Kuil itu untuk Hindu, pengkaji! Kavitha menggeleng sambil tersenyum."}], "clue": "Sikh mempunyai rumah ibadat bernama gurdwara, dengan kubah emas dan bangunan putih."}]}'),
(503, 'e5_n1_s3', 'Nyahkod Lampiran Perkara 3', 'Baca lampiran Perlembagaan yang luntur dan tentukan siapa Ketua Agama Islam di negeri tanpa Raja.', '5', 'Memahami kedudukan agama Islam dalam Perlembagaan Perkara 3.', '{"clueText": "Lampiran lama menulis: Perkara 3(1): Islam agama Persekutuan, agama lain aman dan damai. Perkara 3(2): Raja ialah Ketua Agama Islam di negeri beraja. Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, pemegang kedudukan itu sudah luntur dan tidak kelihatan.", "options": [{"text": "Yang di-Pertuan Agong, bagi Melaka, Pulau Pinang, Sabah dan Sarawak.", "isCorrect": true}, {"text": "Raja setiap negeri itu, bagi Melaka, Pulau Pinang, Sabah dan Sarawak.", "isCorrect": false, "consequence": "Lampiran itu dibaca salah. Murid menyangka negeri tanpa Raja pun mempunyai Raja sebagai Ketua Agama Islam."}, {"text": "Yang di-Pertua Negeri sebagai Ketua Agama Islam, bagi empat negeri itu.", "isCorrect": false, "consequence": "Lampiran itu disalah faham. Murid menyangka ketua negeri dilantik ialah Ketua Agama Islam di situ."}], "aftermath": "Lampiran Perlembagaan disalah baca. Murid pulang dengan fahaman salah tentang Ketua Agama Islam.", "turns": [{"after": 6, "options": [{"text": "Yang di-Pertuan Agong.", "isCorrect": true, "reaction": "Tepat, pengkaji! Perkara 3(3) menyatakannya. Murid itu menulis laju-laju dalam buku."}, {"text": "Raja negeri itu.", "isCorrect": false, "reaction": "Sabah tiada Raja, pengkaji! Murid itu mengerut dahi dan mencoret jawapannya."}, {"text": "Yang di-Pertua Negeri.", "isCorrect": false, "reaction": "Yang di-Pertua Negeri ialah ketua negeri, bukan Ketua Agama Islam di Sabah, pengkaji. Cuba lagi!"}], "clue": "Perkara 3(3) menyebut Melaka, Pulau Pinang, Sabah dan Sarawak, negeri tanpa Raja."}]}'),
(504, 'e5_n1_s4', 'Padanan Kepercayaan Orang Asli', 'Padankan setiap suku Orang Asli dengan kepercayaan atau upacaranya.', '4', 'Mengenal pasti kepercayaan masyarakat Orang Asli di Semenanjung.', '{"pairs": [{"text": "Suku Mah Meri", "pair": 1}, {"text": "Upacara Puja Pantai untuk perlindungan daripada semangat laut", "pair": 1}, {"text": "Kepercayaan tentang penyakit", "pair": 2}, {"text": "Disebabkan kuasa jahat", "pair": 2}, {"text": "Suku Temiar dan Semai", "pair": 3}, {"text": "Upacara ritual untuk menghalau kuasa jahat", "pair": 3}], "aftermath": "Kepercayaan Orang Asli tersalah padan. Pak Mah Meri dan Tok Batin terkilan melihat catatan itu.", "turns": [{"after": 4, "options": [{"text": "Memohon perlindungan dan pengampunan daripada semangat laut.", "isCorrect": true, "reaction": "Betul, pengkaji! Ombak pun macam bertepuk tangan. Pak Mah Meri tersenyum lebar."}, {"text": "Menghalau kuasa jahat daripada badan orang yang sedang sakit.", "isCorrect": false, "reaction": "Itu tujuan upacara ritual Temiar dan Semai, pengkaji. Puja Pantai lain tujuannya!"}, {"text": "Meraikan musim padi di bukit bersama keluarga seluruh kampung.", "isCorrect": false, "reaction": "Padi bukit bukan tentang Puja Pantai, pengkaji. Pak Mah Meri ketawa."}], "clue": "Puja Pantai diadakan di tepi laut, untuk semangat laut."}]}'),
(505, 'e5_n1_s5', 'Padanan Iban dan Kadazandusun', 'Padankan setiap kepercayaan atau upacara dengan masyarakat dan tokoh yang betul.', '4', 'Mengenal pasti kepercayaan masyarakat Iban dan Kadazandusun.', '{"pairs": [{"text": "Iban: Petara", "pair": 1}, {"text": "Dewa yang menyampaikan petanda melalui mimpi dan bayangan", "pair": 1}, {"text": "Iban: Miring", "pair": 2}, {"text": "Upacara dimulai dengan jampi mentera oleh Lemambang", "pair": 2}, {"text": "Kadazandusun: Kinorohingan", "pair": 3}, {"text": "Tuhan untuk meminta sesuatu", "pair": 3}, {"text": "Kadazandusun: Magavau", "pair": 4}, {"text": "Upacara semangat padi yang diketuai Bobohizan", "pair": 4}], "aftermath": "Kepercayaan Iban dan Kadazandusun bertukar tempat. Apai dan Linda terpinga-pinga melihat nota kau.", "turns": [{"after": 5, "options": [{"text": "Lemambang.", "isCorrect": true, "reaction": "Tepat, pengkaji! Apai Jelani menepuk lutut dan Linda mengangkat ibu jari."}, {"text": "Bobohizan.", "isCorrect": false, "reaction": "Bobohizan ialah ketua bomoh Magavau Kadazandusun, pengkaji! Apai ketawa sambil menggeleng."}, {"text": "Petara sendiri.", "isCorrect": false, "reaction": "Petara ialah dewa yang dipuja, pengkaji, bukan yang melakukan upacara. Cuba lagi!"}], "clue": "Penyair yang melakukan upacara Miring dikenali dengan satu gelaran khas."}]}'),
(506, 'e5_n1_s6', 'Nyahkod Nota Bisaya dan Bajau', 'Baca nota lama yang luntur dan tentukan upacara Bajau di Semporna.', '5', 'Mengenal pasti kepercayaan masyarakat Bisaya dan Bajau.', '{"clueText": "Nota lama menulis: Bisaya membaca jampi mentera sebelum membuka kawasan pertanian baharu dan mengadakan Tamarok untuk pesakit. Bajau di Kota Belud mengadakan Ngeduang. Nama upacara Bajau di Semporna sudah luntur dan tidak kelihatan.", "options": [{"text": "Mag''ombo, menghargai warisan turun-temurun agar dirahmati.", "isCorrect": true}, {"text": "Ngeduang, menjamu tetamu sebagai sedekah selepas kematian.", "isCorrect": false, "consequence": "Nota itu disalin dengan nama upacara yang salah. Pembaca menyangka Ngeduang diamalkan di pantai timur."}, {"text": "Tamarok, menghalau kuasa ghaib daripada badan pesakit.", "isCorrect": false, "consequence": "Nota itu bercampur dengan upacara Bisaya. Pembaca menyangka Bajau Semporna mengamalkan Tamarok."}], "aftermath": "Nota tersalah baca. Upacara Bajau dan Bisaya bercampur dalam catatan kau.", "turns": [{"after": 4, "options": [{"text": "Pantai barat Sabah, Kota Belud.", "isCorrect": true, "reaction": "Tepat, pengkaji! Pak Bajau mengangkat ibu jari dan petani Bisaya tersenyum."}, {"text": "Pantai timur Sabah, Semporna.", "isCorrect": false, "reaction": "Itu tempat Mag''ombo, pengkaji! Pak Bajau ketawa dan menunjuk ke arah timur."}, {"text": "Kawasan pertanian Bisaya di Sarawak.", "isCorrect": false, "reaction": "Itu kawasan Tamarok, pengkaji! Pak Bajau menggeleng sambil tersenyum."}], "clue": "Ngeduang diamalkan di pantai barat, manakala Mag''ombo di pantai timur."}]}'),
(507, 'e5_n2_s1', 'Padanan Wakil dan Agama', 'Padankan setiap wakil dengan agama atau ajaran yang diwakilinya.', '4', 'Mengenal pasti tujuh agama dan ajaran di Malaysia.', '{"pairs": [{"text": "Aishah", "pair": 1}, {"text": "Islam", "pair": 1}, {"text": "Daniel", "pair": 2}, {"text": "Kristian", "pair": 2}, {"text": "Mei Ling", "pair": 3}, {"text": "Buddha", "pair": 3}, {"text": "Kavitha", "pair": 4}, {"text": "Hindu", "pair": 4}, {"text": "Harjit", "pair": 5}, {"text": "Sikh", "pair": 5}, {"text": "Kenny", "pair": 6}, {"text": "Ajaran Tao dan Ajaran Konfusius", "pair": 6}], "aftermath": "Wakil tersalah padan. Persidangan terhenti sementara dan murid-murid keliru tentang agama setiap wakil.", "turns": [{"after": 6, "options": [{"text": "Aishah wakil Islam dan Harjit wakil Sikh.", "isCorrect": true, "reaction": "Tepat, Bobohizan! Aishah dan Harjit mengangguk, dan loceng kecil berdenting riang."}, {"text": "Daniel wakil Hindu dan Kavitha wakil Kristian.", "isCorrect": false, "reaction": "Tertukar, Bobohizan! Daniel dan Kavitha berpandangan lalu ketawa."}, {"text": "Mei Ling wakil Sikh dan Harjit wakil Buddha.", "isCorrect": false, "reaction": "Silap, Bobohizan! Mei Ling dan Harjit saling menggeleng sambil tersenyum."}], "clue": "Aishah memperkenalkan dirinya sebagai wakil Islam, Harjit sebagai wakil Sikh."}]}'),
(508, 'e5_n2_s2', 'Misi Bukit: Cari Rumah Ibadat', 'Cari rumah ibadat bagi enam kumpulan agama pada gambar.', '2', 'Mengenal pasti rumah ibadat pelbagai agama di Malaysia.', '{"bgImage": "../assets/gameAsset/background/tempat_beribadat_semua.png", "hotspots": [{"name": "Masjid: rumah ibadat bagi penganut Islam", "top": "25%", "left": "18%"}, {"name": "Gereja: rumah ibadat bagi penganut Kristian", "top": "15%", "left": "40%"}, {"name": "Kuil: rumah ibadat bagi penganut Hindu", "top": "30%", "left": "55%"}, {"name": "Gurdwara: rumah ibadat bagi penganut Sikh", "top": "48%", "left": "18%"}, {"name": "Wat atau tokong: rumah ibadat bagi penganut Buddha", "top": "55%", "left": "53%"}, {"name": "Tokong: rumah ibadat bagi Ajaran Konfusius dan Ajaran Tao", "top": "65%", "left": "32%"}], "aftermath": "Rumah ibadat tersalah tunjuk. Murid-murid turun bukit dengan nama bangunan yang bercampur.", "turns": [{"after": 6, "options": [{"text": "Tokong, untuk Buddha, Ajaran Konfusius dan Ajaran Tao.", "isCorrect": true, "reaction": "Tepat, Bobohizan! Mei Ling bertepuk tangan dan lampu tokong pun menyala."}, {"text": "Gereja, untuk Buddha, Ajaran Konfusius dan Ajaran Tao.", "isCorrect": false, "reaction": "Gereja itu milik Kristian, Bobohizan! Daniel melambai sambil ketawa."}, {"text": "Kuil, untuk Buddha, Ajaran Konfusius dan Ajaran Tao.", "isCorrect": false, "reaction": "Kuil itu untuk Hindu, Bobohizan! Kavitha menggeleng sambil tersenyum."}], "clue": "Mei Ling berkata tokong digunakan oleh tiga kumpulan: Buddha, Konfusius dan Tao."}]}'),
(509, 'e5_n2_s3', 'Soalan Mata Penentu Perlembagaan', 'Bantu murid memahami Perkara 3 dengan menjawab soalan tentang Ketua Agama Islam.', '3', 'Memahami kedudukan agama Islam dalam Perlembagaan Perkara 3.', '{"prompt": "Seorang murid menahan kau dan bertanya: yang manakah pernyataan Perkara 3 yang betul?", "options": [{"text": "Islam agama Persekutuan; agama lain aman. Raja ketua agama di negeri beraja; Yang di-Pertuan Agong di negeri tanpa Raja dan Wilayah Persekutuan.", "isCorrect": true}, {"text": "Islam agama Persekutuan; agama lain dilarang. Raja ketua agama di semua negeri; Yang di-Pertuan Agong tiada peranan di mana-mana negeri.", "isCorrect": false, "consequence": "Murid menyangka agama lain dilarang dan Raja ketua di semua negeri. Cikgu terpaksa membetulkan dengan panjang lebar."}, {"text": "Islam agama Persekutuan; agama lain aman. Yang di-Pertua Negeri ketua agama di Melaka, Pulau Pinang, Sabah dan Sarawak, dan Raja di Wilayah Persekutuan.", "isCorrect": false, "consequence": "Murid menyangka ketua negeri ialah Ketua Agama Islam. Jawapan itu tersebar dan menjadi kekeliruan."}], "aftermath": "Perkara 3 disalah faham. Murid pulang dengan nota Perlembagaan yang tersasar.", "turns": [{"after": 5, "options": [{"text": "Yang di-Pertuan Agong.", "isCorrect": true, "reaction": "Tepat, Bobohizan! Perkara 3(5) menyatakannya. Sultan mengangguk dengan senyuman."}, {"text": "Sultan Selangor.", "isCorrect": false, "reaction": "Bukan, Bobohizan! Kuala Lumpur, Labuan dan Putrajaya di bawah Yang di-Pertuan Agong. Dewan pun berbisik."}, {"text": "Yang di-Pertua Negeri.", "isCorrect": false, "reaction": "Bukan, Bobohizan. Yang di-Pertua Negeri ialah ketua negeri tanpa Raja, bukan Ketua Agama Islam Wilayah Persekutuan."}], "clue": "Perkara 3(5) menyebut Kuala Lumpur, Labuan dan Putrajaya, dan ketuanya orang yang sama dengan Perkara 3(3)."}]}'),
(510, 'e5_n2_s4', 'Nyahkod Catatan Orang Asli', 'Baca catatan lama dan tentukan upacara suku Temiar dan Semai.', '5', 'Mengenal pasti kepercayaan masyarakat Orang Asli di Semenanjung.', '{"clueText": "Catatan lama menulis: suku Mah Meri mengadakan Puja Pantai untuk perlindungan dan pengampunan daripada semangat laut. Orang Asli percaya penyakit disebabkan kuasa jahat. Upacara suku Temiar dan Semai sudah luntur dan tidak kelihatan.", "options": [{"text": "Upacara ritual untuk menghalau kuasa jahat.", "isCorrect": true}, {"text": "Upacara Puja Pantai untuk meminta perlindungan daripada semangat laut.", "isCorrect": false, "consequence": "Catatan itu bercampur dengan upacara Mah Meri. Pembaca menyangka Temiar dan Semai mengadakan Puja Pantai."}, {"text": "Upacara Miring yang dimulakan dengan jampi mentera oleh Lemambang.", "isCorrect": false, "consequence": "Catatan itu bercampur dengan upacara Iban. Pembaca menyangka Temiar dan Semai mengadakan Miring."}], "aftermath": "Catatan Orang Asli disalah baca. Upacara suku-suku itu bercampur dalam ingatan kau.", "turns": [{"after": 4, "options": [{"text": "Disebabkan kuasa jahat.", "isCorrect": true, "reaction": "Tepat, Bobohizan! Tok Batin mengangguk dan murid itu mencatat dengan laju."}, {"text": "Disebabkan semangat padi yang marah.", "isCorrect": false, "reaction": "Semangat padi itu kepercayaan Kadazandusun, Bobohizan! Tok Batin tersenyum dan menggeleng."}, {"text": "Disebabkan Petara yang tidak berpuas hati.", "isCorrect": false, "reaction": "Petara itu dewa orang Iban, Bobohizan! Tok Batin menunjuk ke arah lain."}], "clue": "Tok Batin Temiar menyebut punca penyakit sebelum bercakap tentang ritual."}]}'),
(511, 'e5_n2_s5', 'Soalan Sergahan di Sawah', 'Bantu Linda dan Apai Jelani menjawab soalan tentang kepercayaan Kadazandusun dan Iban.', '3', 'Mengenal pasti kepercayaan masyarakat Iban dan Kadazandusun.', '{"prompt": "Seorang kanak-kanak menahan kau di batas sawah dan bertanya: yang manakah padanan kepercayaan yang betul?", "options": [{"text": "Kadazandusun: Kinorohingan dan Magavau bersama Bobohizan. Iban: Petara dan Miring bersama Lemambang.", "isCorrect": true}, {"text": "Kadazandusun: Petara dan Miring bersama Lemambang. Iban: Kinorohingan dan Magavau bersama Bobohizan.", "isCorrect": false, "consequence": "Kanak-kanak itu mencatat kepercayaan yang tertukar. Linda dan Apai tergelak melihat nota yang silap."}, {"text": "Kadazandusun: Petara dan Magavau bersama Lemambang. Iban: Kinorohingan dan Miring bersama Bobohizan.", "isCorrect": false, "consequence": "Kanak-kanak itu mencatat kepercayaan yang bercampur-campur. Nota itu tidak lagi boleh dipercayai."}], "aftermath": "Kepercayaan Iban dan Kadazandusun bercampur. Kanak-kanak pulang dengan nota yang tersilap.", "turns": [{"after": 4, "options": [{"text": "Bobohizan, ketua bomoh.", "isCorrect": true, "reaction": "Tepat, Bobohizan! Linda bertepuk tangan dan sawah seakan beralun gembira."}, {"text": "Lemambang, penyair Iban.", "isCorrect": false, "reaction": "Lemambang ialah penyair upacara Miring Iban, Bobohizan! Apai Jelani ketawa sambil mengangkat tangan."}, {"text": "Petara, dewa yang dipuja.", "isCorrect": false, "reaction": "Petara ialah dewa Iban, Bobohizan, bukan yang memimpin upacara. Cuba lagi!"}], "clue": "Magavau diketuai oleh ketua bomoh yang dikenali dengan satu gelaran khas, gelaran kau sendiri."}]}'),
(512, 'e5_n2_s6', 'Padanan Upacara Bisaya dan Bajau', 'Padankan setiap upacara dengan masyarakat dan maksud atau tempatnya.', '4', 'Mengenal pasti kepercayaan masyarakat Bisaya dan Bajau.', '{"pairs": [{"text": "Bisaya: jampi mentera", "pair": 1}, {"text": "Dibaca sebelum membuka kawasan pertanian baharu", "pair": 1}, {"text": "Bisaya: Tamarok", "pair": 2}, {"text": "Menghalau kuasa ghaib daripada badan pesakit", "pair": 2}, {"text": "Bajau: Ngeduang", "pair": 3}, {"text": "Menjamu tetamu sebagai sedekah di Kota Belud", "pair": 3}, {"text": "Bajau: Mag''ombo", "pair": 4}, {"text": "Menghargai warisan turun-temurun di Semporna", "pair": 4}], "aftermath": "Upacara Bisaya dan Bajau tersalah padan. Jamuan terhenti dan tetamu saling berpandangan.", "turns": [{"after": 5, "options": [{"text": "Ngeduang di Kota Belud, Mag''ombo di Semporna.", "isCorrect": true, "reaction": "Tepat, Bobohizan! Pak Bajau mengangkat dulang tanda gembira dan jamuan pun bersambung."}, {"text": "Ngeduang di Semporna, Mag''ombo di Kota Belud.", "isCorrect": false, "reaction": "Tertukar, Bobohizan! Pak Bajau ketawa dan membetulkan dulang di tangannya."}, {"text": "Tamarok di Kota Belud, Ngeduang di Semporna.", "isCorrect": false, "reaction": "Tamarok itu upacara Bisaya di Sarawak, Bobohizan! Petani Bisaya mengangkat tangan sambil ketawa."}], "clue": "Pantai barat bersama Kota Belud dan pantai timur bersama Semporna."}]}'),
(513, 'e5_n3_s1', 'Nyahkod Papan Tanda Pesta', 'Baca papan tanda yang luntur dan lengkapkan senarai tiga nama terakhir agama dan ajaran.', '5', 'Mengenal pasti agama dan kepercayaan utama di Malaysia.', '{"clueText": "Papan tanda pesta menulis: Islam, Kristian, Buddha dan Hindu dengan jelas. Tiga nama terakhir sudah luntur dan tidak kelihatan, sedangkan semuanya ada tujuh.", "options": [{"text": "Sikh, Ajaran Tao dan Ajaran Konfusius.", "isCorrect": true}, {"text": "Sikh dan Ajaran Tao sahaja, tanpa Ajaran Konfusius.", "isCorrect": false, "consequence": "Papan tanda ditulis semula dengan hanya enam nama. Penganut Ajaran Konfusius terkilan kerana tidak disebut."}, {"text": "Ajaran Tao dan Ajaran Konfusius sahaja, tanpa Sikh.", "isCorrect": false, "consequence": "Papan tanda ditulis semula tanpa Sikh. Harjit terdiam kerana agamanya tidak tercatat."}], "aftermath": "Papan tanda tidak lengkap. Pesta bermula dengan senarai yang meninggalkan sebahagian agama.", "turns": [{"after": 4, "options": [{"text": "Sikh, Ajaran Tao dan Ajaran Konfusius.", "isCorrect": true, "reaction": "Tepat, Lemambang! Kenny bersorak dan papan tanda pun bercahaya semula!"}, {"text": "Sikh dan Ajaran Tao, tanpa Ajaran Konfusius.", "isCorrect": false, "reaction": "Ajaran Konfusius tertinggal, Lemambang! Kenny menggaru kepala dan ketawa."}, {"text": "Ajaran Tao dan Ajaran Konfusius, tanpa Sikh.", "isCorrect": false, "reaction": "Sikh tertinggal, Lemambang! Harjit melambai dari hujung barisan."}], "clue": "Selepas Hindu, ada Sikh, kemudian dua ajaran: Tao dan Konfusius."}]}'),
(514, 'e5_n3_s2', 'Padanan Pantas: Rumah Ibadat', 'Padankan setiap agama atau ajaran dengan nama rumah ibadatnya.', '4', 'Mengenal pasti rumah ibadat pelbagai agama di Malaysia.', '{"pairs": [{"text": "Islam", "pair": 1}, {"text": "Masjid", "pair": 1}, {"text": "Kristian", "pair": 2}, {"text": "Gereja", "pair": 2}, {"text": "Hindu", "pair": 3}, {"text": "Kuil", "pair": 3}, {"text": "Sikh", "pair": 4}, {"text": "Gurdwara", "pair": 4}, {"text": "Buddha", "pair": 5}, {"text": "Tokong atau wat", "pair": 5}, {"text": "Konfusius dan Tao", "pair": 6}, {"text": "Tokong", "pair": 6}], "aftermath": "Kad rumah ibadat tersalah padan. Murid-murid berjalan ke bangunan yang salah dengan kad yang tersilap.", "turns": [{"after": 5, "options": [{"text": "Konfusius dan Tao dengan tokong.", "isCorrect": true, "reaction": "Tepat, Lemambang! Kad itu melekat di papan dan Mei Ling bersorak!"}, {"text": "Konfusius dan Tao dengan kuil.", "isCorrect": false, "reaction": "Kuil itu rumah ibadat Hindu, Lemambang! Kavitha ketawa sambil menggeleng."}, {"text": "Konfusius dan Tao dengan gurdwara.", "isCorrect": false, "reaction": "Gurdwara rumah ibadat Sikh, Lemambang! Harjit tersenyum dan menggeleng perlahan."}], "clue": "Mei Ling menyebut tokong untuk Buddha, dan juga untuk dua ajaran lain."}]}'),
(515, 'e5_n3_s3', 'Susun Kad Perkara 3', 'Susun Perkara 3 Perlembagaan mengikut nombor dan isinya.', '1', 'Memahami kedudukan agama Islam dalam Perlembagaan Perkara 3.', '{"timelineItems": [{"id": 1, "year": "Perkara 3(1)", "text": "Islam agama bagi Persekutuan; agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan", "why": "Asas kepada seluruh Perkara 3."}, {"id": 2, "year": "Perkara 3(2)", "text": "Di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri itu", "why": "Raja memegang kedudukan di negeri masing-masing."}, {"id": 3, "year": "Perkara 3(3)", "text": "Yang di-Pertuan Agong ialah Ketua Agama Islam di Melaka, Pulau Pinang, Sabah dan Sarawak", "why": "Negeri-negeri ini tidak mempunyai Raja."}, {"id": 4, "year": "Perkara 3(5)", "text": "Yang di-Pertuan Agong ialah Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya", "why": "Wilayah Persekutuan tiada Raja sendiri."}], "aftermath": "Perkara 3 tersusun salah. Murid menyalin urutan yang kelam-kabut ke dalam buku.", "turns": [{"after": 5, "options": [{"text": "3(1), 3(2), 3(3), kemudian 3(5).", "isCorrect": true, "reaction": "Tepat, Lemambang! Murid itu menyusun kad dan dewan bertepuk tangan."}, {"text": "3(5), 3(3), 3(2), kemudian 3(1).", "isCorrect": false, "reaction": "Terbalik, Lemambang! Kad-kad itu bertaburan dan murid mengutipnya sambil ketawa."}, {"text": "3(2), 3(1), 3(5), kemudian 3(3).", "isCorrect": false, "reaction": "Bercampur, Lemambang! Sultan mengerut dahi sambil tersenyum."}], "clue": "Nombor perkara bermula dari kecil ke besar: 3(1), kemudian 3(2) dan seterusnya."}]}'),
(516, 'e5_n3_s4', 'Soalan Sergahan di Pantai', 'Bantu murid memilih padanan kepercayaan Orang Asli yang betul.', '3', 'Mengenal pasti kepercayaan masyarakat Orang Asli di Semenanjung.', '{"prompt": "Seorang murid menahan kau di tepi pantai dan bertanya: yang manakah pernyataan kepercayaan Orang Asli di Semenanjung yang betul?", "options": [{"text": "Mah Meri mengadakan Puja Pantai kepada semangat laut; Temiar dan Semai mengadakan ritual untuk menghalau kuasa jahat.", "isCorrect": true}, {"text": "Mah Meri mengadakan ritual untuk menghalau kuasa jahat; Temiar dan Semai mengadakan Puja Pantai kepada semangat laut.", "isCorrect": false, "consequence": "Murid itu menukar upacara antara suku. Pak Mah Meri dan Tok Batin menggeleng kerana nama suku dan upacara bertukar."}, {"text": "Mah Meri mengadakan Tamarok kepada semangat padi; Temiar dan Semai mengadakan Ngeduang untuk menjamu tetamu.", "isCorrect": false, "consequence": "Murid itu mencampur upacara kaum lain dengan Orang Asli. Catatan itu salah dari awal hingga akhir."}], "aftermath": "Kepercayaan Orang Asli tertukar. Murid pulang dengan padanan suku dan upacara yang salah.", "turns": [{"after": 4, "options": [{"text": "Mah Meri: Puja Pantai. Temiar dan Semai: ritual menghalau kuasa jahat.", "isCorrect": true, "reaction": "Tepat, Lemambang! Ombak bergulung gembira dan Tok Batin mengangguk."}, {"text": "Mah Meri: ritual menghalau kuasa jahat. Temiar dan Semai: Puja Pantai.", "isCorrect": false, "reaction": "Tertukar, Lemambang! Pak Mah Meri dan Tok Batin ketawa melihat jawapan itu."}, {"text": "Mah Meri: Miring. Temiar dan Semai: Magavau.", "isCorrect": false, "reaction": "Miring dan Magavau bukan upacara Orang Asli, Lemambang! Murid itu menggaru kepala."}], "clue": "Puja Pantai berkait dengan laut dan Mah Meri; ritual menghalau kuasa jahat berkait dengan Temiar dan Semai."}]}'),
(517, 'e5_n3_s5', 'Nyahkod Catatan Iban dan Kadazandusun', 'Baca catatan lama dan tentukan gelaran ketua bomoh upacara Magavau.', '5', 'Mengenal pasti kepercayaan masyarakat Iban dan Kadazandusun.', '{"clueText": "Catatan lama menulis: Iban percaya Petara menyampaikan petanda melalui mimpi dan bayangan, dipuja melalui upacara Miring yang dimulai jampi mentera oleh Lemambang. Kadazandusun percaya Kinorohingan dan semangat padi, dengan upacara Magavau diketuai oleh ketua bomoh yang namanya sudah luntur.", "options": [{"text": "Bobohizan, ketua bomoh upacara Magavau.", "isCorrect": true}, {"text": "Lemambang, penyair upacara Miring.", "isCorrect": false, "consequence": "Catatan itu dibaca dengan gelaran Iban. Pembaca menyangka ketua Magavau ialah penyair Miring."}, {"text": "Petara, dewa yang dipuja dalam Miring.", "isCorrect": false, "consequence": "Catatan itu dibaca dengan nama dewa Iban. Pembaca menyangka dewa itu memimpin upacara Kadazandusun."}], "aftermath": "Catatan Iban dan Kadazandusun disalah baca. Gelaran ketua upacara bercampur dalam ingatan.", "turns": [{"after": 4, "options": [{"text": "Bobohizan.", "isCorrect": true, "reaction": "Tepat, Lemambang! Linda menepuk dahi dan bersorak, sambil awan syair beralun di langit."}, {"text": "Lemambang.", "isCorrect": false, "reaction": "Lemambang ialah gelaran penyair Miring Iban, bukan ketua Magavau! Linda ketawa dan Apai tersenyum."}, {"text": "Petara.", "isCorrect": false, "reaction": "Petara ialah dewa yang dipuja dalam Miring. Bukan ketua bomoh Magavau! Linda menggeleng."}], "clue": "Ketua bomoh Magavau Kadazandusun mempunyai gelaran yang berbeza daripada gelaran penyair Miring."}]}'),
(518, 'e5_n3_s6', 'Misi Pantai: Bukti Upacara', 'Cari bukti upacara Bajau pada gambar pantai Semporna dan ingat upacara Bisaya yang diceritakan.', '2', 'Mengenal pasti kepercayaan masyarakat Bisaya dan Bajau.', '{"bgImage": "../assets/gameAsset/background/upacara_pantai.png", "hotspots": [{"name": "Perahu berhias: Mag''ombo, upacara Bajau di Semporna", "top": "30%", "left": "60%"}, {"name": "Gerbang upacara: Mag''ombo menghargai warisan turun-temurun", "top": "50%", "left": "52%"}, {"name": "Tikar jamuan: Ngeduang menjamu tetamu sebagai sedekah, Kota Belud", "top": "75%", "left": "40%"}, {"name": "Rumah di atas air: perkampungan Bajau di pantai timur", "top": "15%", "left": "12%"}], "aftermath": "Bukti upacara tersalah cari. Upacara Bajau dan Bisaya bercampur dalam ingatan.", "turns": [{"after": 4, "options": [{"text": "Mag''ombo, menghargai warisan turun-temurun agar dirahmati.", "isCorrect": true, "reaction": "Tepat, Lemambang! Perahu berhias bergoyang dan Pak Bajau bertepuk tangan."}, {"text": "Ngeduang, menjamu tetamu sebagai sedekah selepas kematian.", "isCorrect": false, "reaction": "Itu Ngeduang di Kota Belud, Lemambang! Pak Bajau ketawa dan menunjuk ke arah barat."}, {"text": "Tamarok, menghalau kuasa ghaib daripada badan pesakit.", "isCorrect": false, "reaction": "Tamarok upacara Bisaya di Sarawak, Lemambang! Petani Bisaya mengangkat tangan sambil ketawa."}], "clue": "Mag''ombo diadakan di Semporna, pantai timur Sabah."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e5_n1_s1', 'hint', 'Tujuh agama dan ajaran: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.', NULL, NULL),
(501, NULL, 'hint', 'Tujuh semuanya. Jangan tertinggal Sikh dan dua ajaran di hujung senarai.', 'Agama dan ajaran di Malaysia: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.', 'Hebat! Tujuh pintu terbuka serentak dan semua wakil melambai gembira.'),
(NULL, 'e5_n1_s2', 'hint', 'Islam: masjid. Kristian: gereja. Hindu: kuil. Sikh: gurdwara. Buddha: tokong atau wat. Konfusius dan Tao: tokong.', NULL, NULL),
(502, NULL, 'hint', 'Masjid, gereja, tokong, wat, kuil dan gurdwara. Enam nama, enam bangunan.', 'Rumah ibadat: Islam, masjid; Kristian, gereja; Hindu, kuil; Sikh, gurdwara; Buddha, tokong atau wat; Konfusius dan Tao, tokong.', 'Hebat! Semua rumah ibadat berjaya dicatat dan murid bersorak.'),
(NULL, 'e5_n1_s3', 'hint', 'Perkara 3(1): Islam agama Persekutuan, agama lain aman. 3(2): Raja ketua agama Islam. 3(3): Yang di-Pertuan Agong untuk Melaka, Pulau Pinang, Sabah, Sarawak. 3(5): Wilayah Persekutuan.', NULL, NULL),
(503, NULL, 'hint', 'Negeri tanpa Raja ialah Melaka, Pulau Pinang, Sabah dan Sarawak. Wilayah Persekutuan juga di bawah Yang di-Pertuan Agong.', 'Perkara 3(1): Islam agama Persekutuan, agama lain diamalkan dengan aman dan damai. 3(2): Raja ialah Ketua Agama Islam di negeri beraja. 3(3): Yang di-Pertuan Agong di Melaka, Pulau Pinang, Sabah dan Sarawak. 3(5): Yang di-Pertuan Agong di Kuala Lumpur, Labuan dan Putrajaya.', 'Betul! Lampiran itu terang semula dan dewan bergema dengan tepukan.'),
(NULL, 'e5_n1_s4', 'hint', 'Mah Meri: Puja Pantai untuk perlindungan dan pengampunan daripada semangat laut. Temiar dan Semai: upacara ritual menghalau kuasa jahat.', NULL, NULL),
(504, NULL, 'hint', 'Mah Meri bersama laut, Temiar dan Semai bersama ritual menghalau kuasa jahat.', 'Orang Asli Semenanjung: suku Mah Meri mengadakan upacara Puja Pantai untuk perlindungan dan pengampunan daripada semangat laut; mereka percaya penyakit disebabkan kuasa jahat; suku Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat.', 'Betul! Catatan kau bercahaya dan Orang Asli tersenyum puas.'),
(NULL, 'e5_n1_s5', 'hint', 'Iban: Petara, petanda melalui mimpi dan bayangan, upacara Miring, Lemambang. Kadazandusun: Kinorohingan, semangat padi, Magavau, Bobohizan.', NULL, NULL),
(505, NULL, 'hint', 'Iban: Petara, Miring dan Lemambang. Kadazandusun: Kinorohingan, Magavau dan Bobohizan.', 'Iban: Petara menyampaikan petanda melalui mimpi dan bayangan; dipuja melalui upacara Miring yang dimulai dengan jampi mentera oleh Lemambang. Kadazandusun: percaya Kinorohingan dan semangat padi, upacara Magavau diketuai Bobohizan.', 'Betul! Dua masyarakat, dua upacara, semuanya tepat dalam nota kau.'),
(NULL, 'e5_n1_s6', 'hint', 'Bisaya: kuasa ghaib, jampi mentera, upacara Tamarok. Bajau: Ngeduang di Kota Belud, Mag''ombo di Semporna.', NULL, NULL),
(506, NULL, 'hint', 'Bisaya: Tamarok. Bajau: Ngeduang di Kota Belud dan Mag''ombo di Semporna.', 'Bisaya di Sarawak, petani, percaya kuasa ghaib: jampi mentera sebelum membuka kawasan pertanian baharu dan upacara Tamarok untuk pesakit. Bajau: Ngeduang (jamuan sedekah, Kota Belud) dan Mag''ombo (menghargai warisan, Semporna).', 'Betul! Nota itu terang semula dan petani bersorak gembira.'),
(NULL, 'e5_n2_s1', 'hint', 'Wakil agama: Aishah (Islam), Daniel (Kristian), Mei Ling (Buddha), Kavitha (Hindu), Harjit (Sikh), Kenny (Ajaran Tao dan Ajaran Konfusius).', NULL, NULL),
(507, NULL, 'hint', 'Islam, Kristian, Buddha, Hindu, Sikh, serta Ajaran Tao dan Ajaran Konfusius.', 'Agama dan ajaran di Malaysia: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.', 'Betul! Loceng berdenting riang dan semua wakil bertepuk tangan.'),
(NULL, 'e5_n2_s2', 'hint', 'Masjid untuk Islam, gereja untuk Kristian, kuil untuk Hindu, gurdwara untuk Sikh, tokong atau wat untuk Buddha, tokong untuk Konfusius dan Tao.', NULL, NULL),
(508, NULL, 'hint', 'Enam bangunan: masjid, gereja, kuil, gurdwara, wat dan tokong. Cari satu persatu.', 'Rumah ibadat: Islam, masjid; Kristian, gereja; Hindu, kuil; Sikh, gurdwara; Buddha, tokong atau wat; Konfusius dan Tao, tokong.', 'Hebat! Semua rumah ibadat ditemui dan murid bersorak dari atas bukit.'),
(NULL, 'e5_n2_s3', 'hint', '3(1) Islam agama Persekutuan, agama lain aman. 3(2) Raja ketua agama. 3(3) Yang di-Pertuan Agong di Melaka, Pulau Pinang, Sabah, Sarawak. 3(5) Wilayah Persekutuan.', NULL, NULL),
(509, NULL, 'hint', 'Islam agama Persekutuan, agama lain aman. Raja dahulu, kemudian Yang di-Pertuan Agong di tempat tanpa Raja.', 'Perkara 3(1): Islam agama Persekutuan, agama lain diamalkan dengan aman dan damai. 3(2): Raja ialah Ketua Agama Islam di negeri beraja. 3(3): Yang di-Pertuan Agong di Melaka, Pulau Pinang, Sabah dan Sarawak. 3(5): Yang di-Pertuan Agong di Kuala Lumpur, Labuan dan Putrajaya.', 'Betul! Dewan Perlembagaan sunyi seketika, kemudian bergema dengan tepukan.'),
(NULL, 'e5_n2_s4', 'hint', 'Mah Meri: Puja Pantai, semangat laut. Orang Asli percaya penyakit disebabkan kuasa jahat. Temiar dan Semai: ritual menghalau kuasa jahat.', NULL, NULL),
(510, NULL, 'hint', 'Mah Meri bersama Puja Pantai. Temiar dan Semai bersama ritual menghalau kuasa jahat.', 'Orang Asli Semenanjung: suku Mah Meri mengadakan upacara Puja Pantai untuk perlindungan dan pengampunan daripada semangat laut; mereka percaya penyakit disebabkan kuasa jahat; suku Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat.', 'Betul! Catatan lama itu terang semula dan ombak pun berbisik gembira.'),
(NULL, 'e5_n2_s5', 'hint', 'Kadazandusun: Kinorohingan, semangat padi, Magavau dan Bobohizan. Iban: Petara, mimpi dan bayangan, Miring, jampi mentera, Lemambang.', NULL, NULL),
(511, NULL, 'hint', 'Kadazandusun: Kinorohingan, Magavau dan Bobohizan. Iban: Petara, Miring dan Lemambang.', 'Kadazandusun: Kinorohingan (Tuhan untuk meminta sesuatu), semangat padi, upacara Magavau diketuai Bobohizan. Iban: Petara menyampaikan petanda melalui mimpi dan bayangan, dipuja melalui upacara Miring yang dimulai dengan jampi mentera oleh Lemambang.', 'Betul! Sawah beralun gembira dan semua penari bertepuk tangan.'),
(NULL, 'e5_n2_s6', 'hint', 'Bisaya: kuasa ghaib, jampi mentera, Tamarok. Bajau: Ngeduang di Kota Belud, Mag''ombo di Semporna.', NULL, NULL),
(512, NULL, 'hint', 'Bisaya: jampi mentera dan Tamarok. Bajau: Ngeduang di Kota Belud dan Mag''ombo di Semporna.', 'Bisaya di Sarawak, petani, percaya kuasa ghaib: jampi mentera sebelum membuka kawasan pertanian baharu dan upacara Tamarok untuk pesakit. Bajau: Ngeduang (jamuan sedekah, Kota Belud) dan Mag''ombo (menghargai warisan, Semporna).', 'Betul! Dulang berpindah tangan dengan gembira dan jamuan bersambung.'),
(NULL, 'e5_n3_s1', 'hint', 'Tujuh agama dan ajaran: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.', NULL, NULL),
(513, NULL, 'hint', 'Islam, Kristian, Buddha, Hindu, kemudian Sikh, Ajaran Tao dan Ajaran Konfusius. Tujuh semuanya.', 'Agama dan ajaran di Malaysia: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.', 'Betul! Papan tanda bercahaya dan semua murid bertepuk tangan.'),
(NULL, 'e5_n3_s2', 'hint', 'Masjid untuk Islam, gereja untuk Kristian, kuil untuk Hindu, gurdwara untuk Sikh, tokong atau wat untuk Buddha, tokong untuk Konfusius dan Tao.', NULL, NULL),
(514, NULL, 'hint', 'Masjid, gereja, kuil, gurdwara, tokong atau wat, dan tokong. Enam pasangan.', 'Rumah ibadat: Islam, masjid; Kristian, gereja; Hindu, kuil; Sikh, gurdwara; Buddha, tokong atau wat; Konfusius dan Tao, tokong.', 'Betul! Kad melekat satu persatu dan angin pun berhenti menyampuk.'),
(NULL, 'e5_n3_s3', 'hint', 'Perkara 3(1), 3(2), 3(3), 3(5): Islam agama Persekutuan, Raja, Yang di-Pertuan Agong di negeri tanpa Raja, dan Wilayah Persekutuan.', NULL, NULL),
(515, NULL, 'hint', 'Susun dari 3(1) hingga 3(5): Islam agama Persekutuan, Raja, empat negeri tanpa Raja, dan Wilayah Persekutuan.', 'Perkara 3(1): Islam agama Persekutuan, agama lain aman dan damai. 3(2): Raja ialah Ketua Agama Islam di negeri beraja. 3(3): Yang di-Pertuan Agong di Melaka, Pulau Pinang, Sabah dan Sarawak. 3(5): Yang di-Pertuan Agong di Kuala Lumpur, Labuan dan Putrajaya.', 'Betul! Empat kad tersusun kemas dan dewan bergema.'),
(NULL, 'e5_n3_s4', 'hint', 'Mah Meri: Puja Pantai untuk perlindungan dan pengampunan daripada semangat laut. Temiar dan Semai: upacara ritual menghalau kuasa jahat. Penyakit dipercayai kuasa jahat.', NULL, NULL),
(516, NULL, 'hint', 'Mah Meri bersama laut dan Puja Pantai. Temiar dan Semai bersama ritual menghalau kuasa jahat.', 'Orang Asli Semenanjung: suku Mah Meri mengadakan upacara Puja Pantai untuk perlindungan dan pengampunan daripada semangat laut; mereka percaya penyakit disebabkan kuasa jahat; suku Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat.', 'Betul! Ombak bergolek dan Orang Asli tersenyum puas.'),
(NULL, 'e5_n3_s5', 'hint', 'Iban: Petara, mimpi dan bayangan, Miring, jampi mentera, Lemambang. Kadazandusun: Kinorohingan, semangat padi, Magavau, Bobohizan.', NULL, NULL),
(517, NULL, 'hint', 'Iban: Petara, Miring, Lemambang. Kadazandusun: Kinorohingan, Magavau dan Bobohizan.', 'Iban: Petara menyampaikan petanda melalui mimpi dan bayangan, dipuja melalui upacara Miring yang dimulai dengan jampi mentera oleh Lemambang. Kadazandusun: percaya Kinorohingan dan semangat padi, upacara Magavau diketuai Bobohizan.', 'Betul! Catatan itu terang semula dan awan syair beralun gembira.'),
(NULL, 'e5_n3_s6', 'hint', 'Bisaya: kuasa ghaib, jampi mentera, Tamarok. Bajau: Ngeduang di Kota Belud, Mag''ombo di Semporna.', NULL, NULL),
(518, NULL, 'hint', 'Cari perahu berhias, gerbang upacara, tikar jamuan dan rumah di atas air. Ingat Tamarok milik Bisaya.', 'Bisaya di Sarawak, petani, percaya kuasa ghaib: jampi mentera sebelum membuka kawasan pertanian baharu dan upacara Tamarok untuk pesakit. Bajau: Ngeduang (jamuan sedekah, Kota Belud) dan Mag''ombo (menghargai warisan, Semporna).', 'Hebat! Empat bukti ditemui dan pantai bergema dengan tepukan.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(81, 501, NULL, 'Tugasku ialah mencatat agama dan kepercayaan dengan jujur supaya semua kaum saling memahami. Jika pengkaji berhenti mencatat, kita mudah salah faham, {nama}. Terima kasih kerana meminjamkan jiwa!', 1),
(81, 501, NULL, 'Setiap agama dan kepercayaan perlu dikenali dengan hormat. Apabila kita memahami jiran kita, kehidupan bersama menjadi lebih aman dan damai.', 2),
(81, 501, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengkaji yang mengembara dengan buku nota lapangan. Pena dibuka, misi bermula! Catat setiap agama dan kepercayaan dengan adil dan hormat.', 3),
(84, 501, 'e5_n1_s1', 'Pengkaji! Selamat datang ke Taman Tujuh Pintu! Aishah di sini, wakil Islam. Misi pertama kau: kenal semua wakil sebelum matahari terbenam. Siap sedia, ya?', 1),
(NULL, 501, 'e5_n1_s1', 'Siap! Pena sudah dibuka, buku nota sudah dibentang. Siapa seterusnya?', 2),
(85, 501, 'e5_n1_s1', 'Daniel wakil Kristian! Salam sejahtera, pengkaji. Mei Ling dari Buddha di sebelah saya, dan dia malu-malu sikit.', 3),
(86, 501, 'e5_n1_s1', 'Mana ada malu! Mei Ling sedia, pengkaji. Itu Kavitha untuk Hindu, dan Harjit untuk Sikh, yang paling tenang antara kami.', 4),
(87, 501, 'e5_n1_s1', 'Pengkaji, jangan lupa catat nama dengan betul. Saya Hindu, dia Sikh. Dua pintu, dua agama, tapi kami berkawan sejak kecil!', 5),
(89, 501, 'e5_n1_s1', 'Dan saya Kenny, wakil Ajaran Tao dan Ajaran Konfusius. Dua ajaran, satu orang, jimat tempat duduk! Pengkaji, teka: dua ajaran apakah yang saya wakili?', 6),
(98, 501, 'e5_n1_s2', 'Pengkaji! Pengkaji! Saya bawa kamera sekolah! Misi kita: cari semua rumah ibadat di jalan ini. Mana satu masjid, mana satu gereja?', 1),
(84, 501, 'e5_n1_s2', 'Aishah bantu! Rumah ibadat Islam ialah masjid, dan ia ada kubah hijau dengan menara yang tinggi.', 2),
(85, 501, 'e5_n1_s2', 'Gereja untuk Kristian, pengkaji! Menara bersilang itu milik kami. Cantik, kan? Kami bangga!', 3),
(87, 501, 'e5_n1_s2', 'Kuil untuk Hindu, dengan menara berwarna-warni. Dan itu gurdwara, untuk Sikh, dengan kubah emas.', 4),
(86, 501, 'e5_n1_s2', 'Buddha ada tokong atau wat. Tokong juga digunakan untuk Ajaran Konfusius dan Ajaran Tao. Satu nama, tiga penghuni!', 5),
(98, 501, 'e5_n1_s2', 'Wah! Pengkaji, cepat tunjuk pada gambar: mana satu rumah ibadat Sikh?', 6),
(98, 501, 'e5_n1_s3', 'Pengkaji, cikgu kata Perkara 3 itu penting untuk peperiksaan! Cepat, ceritakan apa maksudnya!', 1),
(NULL, 501, 'e5_n1_s3', 'Perkara 3(1): Islam adalah agama bagi Persekutuan, tetapi agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.', 2),
(96, 501, 'e5_n1_s3', 'Beta menyambung, pengkaji. Perkara 3(2): di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri itu.', 3),
(97, 501, 'e5_n1_s3', 'Dan saya wakil negeri tanpa Raja. Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, Yang di-Pertuan Agong ialah Ketua Agama Islam.', 4),
(96, 501, 'e5_n1_s3', 'Perkara 3(5) pula, pengkaji: Yang di-Pertuan Agong ialah Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya.', 5),
(98, 501, 'e5_n1_s3', 'Wah, banyak nombor! Pengkaji, di Sabah, siapakah Ketua Agama Islamnya?', 6),
(91, 501, 'e5_n1_s4', 'Selamat datang, pengkaji! Saya Pak Mah Meri. Hari ini kami mengadakan Puja Pantai, upacara memohon perlindungan dan pengampunan daripada semangat laut. Dengar ombak itu, pengkaji!', 1),
(NULL, 501, 'e5_n1_s4', 'Wah, jadi Puja Pantai itu untuk perlindungan dan pengampunan. Boleh saya catat, Pak?', 2),
(90, 501, 'e5_n1_s4', 'Catatlah, pengkaji. Kami suku Temiar dan Semai percaya penyakit datang daripada kuasa jahat. Kami adakan upacara ritual untuk menghalau kuasa jahat itu.', 3),
(91, 501, 'e5_n1_s4', 'Itulah kepercayaan kami, pengkaji. Orang Asli di Semenanjung menjaga laut, hutan dan tubuh dengan upacara. Cuba kau ulang, apa tujuan Puja Pantai?', 4),
(92, 501, 'e5_n1_s5', 'Pengkaji, Apai Jelani ini orang Iban. Kami percaya Petara, dewa kami, menyampaikan petanda dan alamat melalui mimpi dan bayangan. Mimpi pun boleh jadi surat!', 1),
(NULL, 501, 'e5_n1_s5', 'Wah, surat melalui mimpi! Bagaimana Petara dipuja, Apai?', 2),
(92, 501, 'e5_n1_s5', 'Melalui upacara Miring, pengkaji. Miring dimulai dengan jampi mentera, dan dilakukan oleh seorang penyair dikenali sebagai Lemambang.', 3),
(93, 501, 'e5_n1_s5', 'Linda dari Kadazandusun pula! Kami percaya Kinorohingan, Tuhan untuk meminta sesuatu. Kami juga percaya semangat padi, jadi kami adakan upacara Magavau.', 4),
(93, 501, 'e5_n1_s5', 'Magavau diketuai oleh ketua bomoh yang dikenali sebagai Bobohizan. Pengkaji, kau teka: siapa yang melakukan upacara Miring?', 5),
(94, 501, 'e5_n1_s6', 'Salam, pengkaji! Saya petani Bisaya. Kami percaya kuasa ghaib. Sebelum membuka kawasan pertanian baharu, kami baca jampi mentera supaya tidak ada gangguan.', 1),
(94, 501, 'e5_n1_s6', 'Jika ada orang sakit, kami adakan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit. Bau asapnya wangi, pengkaji!', 2),
(95, 501, 'e5_n1_s6', 'Pak Bajau datang menyampuk! Kami orang Bajau menjalankan upacara Ngeduang di pantai barat Sabah, Kota Belud. Keluarga si mati menjamu makanan kepada tetamu sebagai sedekah.', 3),
(95, 501, 'e5_n1_s6', 'Orang Bajau di pantai timur, Semporna, pula mengadakan Mag''ombo. Mag''ombo bermaksud menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati. Pengkaji, di manakah Ngeduang diamalkan?', 4),
(82, 502, NULL, 'Tugasku ialah menjaga cerita kepercayaan setiap kaum supaya tidak lenyap seperti kabus pagi. Jika penjaga adat berdiam diri, anak cucu lupa asal mereka, {nama}. Terima kasih kerana meminjamkan jiwa!', 1),
(82, 502, NULL, 'Setiap kaum menjaga kepercayaannya dengan cara sendiri. Apabila kita belajar menghormati cara itu, kita hidup aman seperti padi yang tumbuh sama tinggi.', 2),
(82, 502, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga padi yang dijemput ke persidangan para penjaga adat. Loceng kecil berdenting, semangat padi pun menanti. Dengarlah dengan telinganya dan bercakaplah dengan suaranya.', 3),
(98, 502, 'e5_n2_s1', 'Bobohizan! Bobohizan! Murid sekolah dijemput ke persidangan ini. Cikgu kata kita mesti kenal tujuh agama dan ajaran. Tujuh? Banyaknya!', 1),
(NULL, 502, 'e5_n2_s1', 'Ssshh, jangan cemas, anak. Semangat padi pun belajar satu persatu. Marilah, kita bertemu wakil mereka dengan hormat.', 2),
(84, 502, 'e5_n2_s1', 'Aishah wakil Islam. Terima kasih sudah sudi datang, Bobohizan. Di sebelah saya, Daniel untuk Kristian.', 3),
(85, 502, 'e5_n2_s1', 'Betul tu! Daniel yang pandai berjenaka tapi kali ini serius. Mei Ling di sana wakil Buddha, dan Kavitha untuk Hindu.', 4),
(88, 502, 'e5_n2_s1', 'Saya Harjit, wakil Sikh. Orang pertama yang tersenyum bila ditanya, kata orang!', 5),
(89, 502, 'e5_n2_s1', 'Kenny di hujung! Wakil Ajaran Tao dan Ajaran Konfusius, dua ajaran, satu kerusi. Bobohizan, bantu padankan nama kami dengan agama, ya?', 6),
(98, 502, 'e5_n2_s2', 'Bobohizan, dari atas bukit ini nampak banyak bangunan! Itu rumah ibadat, kan? Nama masing-masing apa?', 1),
(NULL, 502, 'e5_n2_s2', 'Ya, anak. Setiap bangunan itu rumah doa. Ada masjid, gereja, kuil, gurdwara, tokong dan wat. Lihat betul-betul!', 2),
(84, 502, 'e5_n2_s2', 'Masjid untuk Islam, Bobohizan! Kubahnya berwarna merah jambu di sebelah sana.', 3),
(87, 502, 'e5_n2_s2', 'Kuil untuk Hindu. Menara warna-warni itu milik kami, Bobohizan. Cantik, kan?', 4),
(86, 502, 'e5_n2_s2', 'Tokong atau wat untuk Buddha. Tokong yang sama juga untuk Ajaran Konfusius dan Ajaran Tao. Gereja untuk Kristian, gurdwara untuk Sikh.', 5),
(98, 502, 'e5_n2_s2', 'Bobohizan, cepat tunjuk pada gambar! Cari masjid, gereja, kuil, gurdwara dan tokong!', 6),
(96, 502, 'e5_n2_s3', 'Selamat datang, Bobohizan. Beta mahu menerangkan Perkara 3. Perkara 3(1): Islam adalah agama bagi Persekutuan, tetapi agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.', 1),
(NULL, 502, 'e5_n2_s3', 'Wah, jadi setiap agama dijaga dengan aman. Sama macam kampung kami, setiap upacara ada tempatnya.', 2),
(96, 502, 'e5_n2_s3', 'Perkara 3(2): di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri beraja itu.', 3),
(97, 502, 'e5_n2_s3', 'Saya dari negeri tanpa Raja. Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, Yang di-Pertuan Agong ialah Ketua Agama Islam.', 4),
(97, 502, 'e5_n2_s3', 'Perkara 3(5): Yang di-Pertuan Agong juga Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya. Bobohizan, soalan untuk kau: siapa Ketua Agama Islam Wilayah Persekutuan?', 5),
(91, 502, 'e5_n2_s4', 'Bobohizan dari Sabah! Jauh kau datang. Saya Pak Mah Meri. Di sini kami mengadakan upacara Puja Pantai untuk memohon perlindungan dan pengampunan daripada semangat laut.', 1),
(NULL, 502, 'e5_n2_s4', 'Semangat laut, ya? Di kampung saya, kami pun ada semangat padi. Setiap kaum menjaga dengan cara masing-masing.', 2),
(90, 502, 'e5_n2_s4', 'Tok Batin Temiar berkata: orang Asli percaya penyakit disebabkan kuasa jahat. Kami suku Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat itu.', 3),
(98, 502, 'e5_n2_s4', 'Bobohizan, saya hendak kuiz! Apakah yang Orang Asli percayai tentang punca penyakit?', 4),
(93, 502, 'e5_n2_s5', 'Bobohizan, Linda di sini! Matahari terbit di atas sawah macam lukisan. Kami percaya Kinorohingan, Tuhan untuk meminta sesuatu. Apa pun kita pinta, kita sebut nama itu.', 1),
(NULL, 502, 'e5_n2_s5', 'Betul, anak. Kami juga percaya semangat padi. Kerana itu kami menjalankan upacara Magavau, dan Bobohizan yang memimpinnya, itulah tugas aku!', 2),
(92, 502, 'e5_n2_s5', 'Apai Jelani, orang Iban, menumpang berbual. Kami percaya Petara menyampaikan petanda dan alamat melalui mimpi dan bayangan. Kami memujanya melalui upacara Miring.', 3),
(92, 502, 'e5_n2_s5', 'Miring dimulai dengan jampi mentera, dan dilakukan oleh penyair yang dikenali sebagai Lemambang. Bobohizan, siapa yang memimpin upacara Magavau?', 4),
(95, 502, 'e5_n2_s6', 'Selamat datang, Bobohizan! Pak Bajau jemput makan dahulu. Di Kota Belud, pantai barat Sabah, keluarga si mati menjamu makanan kepada tetamu sebagai sedekah. Itulah upacara Ngeduang.', 1),
(NULL, 502, 'e5_n2_s6', 'Terima kasih, Pak. Jamuan sebagai sedekah, bunyi macam adat kampung saya juga.', 2),
(94, 502, 'e5_n2_s6', 'Petani Bisaya pun menumpang. Kami di Sarawak percaya kuasa ghaib. Jampi mentera dibaca sebelum membuka kawasan pertanian baharu supaya tiada gangguan.', 3),
(94, 502, 'e5_n2_s6', 'Kalau ada pesakit, kami adakan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', 4),
(95, 502, 'e5_n2_s6', 'Orang Bajau di pantai timur, Semporna, mengadakan Mag''ombo, menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati. Bobohizan, padankan upacara dengan tempatnya!', 5),
(83, 503, NULL, 'Tugasku ialah melagukan syair supaya kepercayaan setiap kaum difahami dan dihormati. Jika penyair senyap, bait-bait lama pun lenyap, {nama}. Terima kasih kerana meminjamkan suara!', 1),
(83, 503, NULL, 'Setiap agama dan kepercayaan ialah satu bait dalam syair besar negara kita. Apabila semua bait dilagukan bersama, Malaysia berbunyi merdu.', 2),
(83, 503, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penyair yang melagukan jampi mentera dan syair pujian. Suaramu bergema, sekolah pun senyap menanti! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(98, 503, 'e5_n3_s1', 'Lemambang! Lemambang! Papan tanda pesta ini luntur terkena hujan semalam! Boleh Lemambang nyanyikan semula senarai agama?', 1),
(NULL, 503, 'e5_n3_s1', 'Hai, anak cucu! Syair bermula begini: Islam, Kristian, Buddha, Hindu. Empat nama itu masih jelas pada papan tanda, bukan?', 2),
(84, 503, 'e5_n3_s1', 'Jelas, Lemambang! Tapi tiga nama terakhir pudar. Aishah sendiri pun tak nampak, hehe.', 3),
(89, 503, 'e5_n3_s1', 'Kenny pun tak nampak! Hmm, nama saya pun hilang? Aduh, Lemambang, tolong baca tiga nama terakhir itu!', 4),
(98, 503, 'e5_n3_s2', 'Lemambang! Murid-murid dapat kad nama rumah ibadat, tapi kad itu bertaburan ditiup angin! Boleh Lemambang tolong susun semula?', 1),
(NULL, 503, 'e5_n3_s2', 'Hai, tenanglah, anak cucu! Syair ini pun ada rentaknya. Islam dengan masjid, Kristian dengan gereja.', 2),
(87, 503, 'e5_n3_s2', 'Hindu dengan kuil, Lemambang! Cepat, jangan sampai angin bawa kad itu ke pantai!', 3),
(88, 503, 'e5_n3_s2', 'Sikh dengan gurdwara. Harjit pegang kadnya erat-erat, Lemambang. Tak mahu hilang!', 4),
(86, 503, 'e5_n3_s2', 'Buddha dengan tokong atau wat. Tokong juga untuk Ajaran Konfusius dan Ajaran Tao. Lemambang, padankan semua kad ya!', 5),
(98, 503, 'e5_n3_s3', 'Lemambang, cikgu kata Perkara 3 ada empat bahagian. Tapi kad saya bercampur, dan saya tak ingat susunannya!', 1),
(NULL, 503, 'e5_n3_s3', 'Tenang, anak. Syair ini ada urutannya. Mulakan dengan Perkara 3(1): Islam adalah agama bagi Persekutuan, tetapi agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.', 2),
(96, 503, 'e5_n3_s3', 'Beta menyambung. Perkara 3(2): di negeri yang mempunyai Raja, kedudukan Raja ialah Ketua Agama Islam di negeri itu.', 3),
(97, 503, 'e5_n3_s3', 'Perkara 3(3): bagi Melaka, Pulau Pinang, Sabah dan Sarawak, Yang di-Pertuan Agong ialah Ketua Agama Islam. Perkara 3(5): Yang di-Pertuan Agong juga Ketua Agama Islam Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya.', 4),
(98, 503, 'e5_n3_s3', 'Wah, banyaknya! Lemambang, tolong susun kad saya mengikut nombor Perkara!', 5),
(91, 503, 'e5_n3_s4', 'Lemambang, selamat datang ke pantai! Orang Mah Meri mengadakan Puja Pantai untuk memohon perlindungan dan pengampunan daripada semangat laut. Dengar ombak, itu suara semangat laut.', 1),
(NULL, 503, 'e5_n3_s4', 'Merdu sekali, Pak! Syair kami di Sarawak pun begitu. Setiap kaum menyanyi mengikut alamnya.', 2),
(90, 503, 'e5_n3_s4', 'Tok Batin Temiar bercerita. Orang Asli percaya penyakit disebabkan kuasa jahat. Suku Temiar dan Suku Semai mengadakan upacara ritual untuk menghalau kuasa jahat itu.', 3),
(98, 503, 'e5_n3_s4', 'Lemambang, saya nak tanya! Mana satu padanan yang betul tentang kepercayaan Orang Asli?', 4),
(92, 503, 'e5_n3_s5', 'Lemambang! Betul-betul orang kita! Apai Jelani mahu bercerita. Kami orang Iban percaya Petara menyampaikan petanda dan alamat melalui mimpi dan bayangan.', 1),
(NULL, 503, 'e5_n3_s5', 'Betul, Apai. Kita memuja Petara melalui upacara Miring. Miring dimulai dengan jampi mentera, dan dilakukan oleh penyair, Lemambang, iaitu saya sendiri, hai!', 2),
(93, 503, 'e5_n3_s5', 'Linda dari Kadazandusun menumpang. Kami percaya Kinorohingan, Tuhan untuk meminta sesuatu. Kami juga percaya semangat padi dan menjalankan upacara Magavau.', 3),
(93, 503, 'e5_n3_s5', 'Upacara Magavau diketuai oleh ketua bomoh yang dikenali sebagai ... eh, nama itu terlupa pula! Lemambang, tolong baca catatan ini dahulu!', 4),
(94, 503, 'e5_n3_s6', 'Lemambang! Petani Bisaya datang jauh dari Sarawak. Kami percaya kuasa ghaib. Jampi mentera dibaca sebelum membuka kawasan pertanian baharu supaya tiada gangguan.', 1),
(94, 503, 'e5_n3_s6', 'Bila ada pesakit, kami adakan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', 2),
(95, 503, 'e5_n3_s6', 'Pak Bajau pula, Lemambang! Di pantai barat Sabah, Kota Belud, keluarga si mati menjamu makanan kepada tetamu sebagai sedekah. Itulah upacara Ngeduang.', 3),
(95, 503, 'e5_n3_s6', 'Di pantai timur, Semporna, kami mengadakan Mag''ombo, bermaksud menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati. Lemambang, cari bukti upacara pantai ini pada gambar!', 4);
INSERT INTO QuestionBank (bankID, eraID) VALUES (5, 5)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(501, 5, 'Antara berikut, yang manakah agama atau ajaran di Malaysia?', 'Ajaran Konfusius', 'Ajaran Magavau', 'Ajaran Miring', 'Ajaran Tamarok', 'A', 'Ingat tujuh agama dan ajaran dalam senarai.', 'Agama dan ajaran di Malaysia ialah Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.'),
(502, 5, 'Berapakah bilangan agama dan ajaran yang disenaraikan di Malaysia?', 'Lima', 'Enam', 'Sembilan', 'Tujuh', 'D', 'Kira Islam hingga Ajaran Konfusius.', 'Tujuh: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Tao dan Ajaran Konfusius.'),
(503, 5, 'Antara berikut, yang manakah ialah satu daripada agama di Malaysia?', 'Sikh', 'Kinorohingan', 'Petara', 'Bobohizan', 'A', 'Pilih nama agama, bukan nama dewa atau tokoh.', 'Sikh ialah salah satu agama di Malaysia, manakala Kinorohingan dan Petara ialah kepercayaan kaum dan Bobohizan ialah gelaran ketua bomoh.'),
(504, 5, 'Ajaran manakah dipasangkan dengan Ajaran Konfusius dalam senarai agama Malaysia?', 'Ajaran Sikh', 'Ajaran Tao', 'Ajaran Hindu', 'Ajaran Kristian', 'B', 'Dua ajaran yang berkongsi tokong.', 'Ajaran Tao dan Ajaran Konfusius ialah dua ajaran dalam senarai tujuh agama dan ajaran.'),
(505, 5, 'Mengapakah penting kita mengenali agama dan kepercayaan lain?', 'Supaya semua orang menganut satu agama sahaja', 'Supaya perbezaan agama dapat dihapuskan kelak', 'Supaya agama lain tidak lagi diamalkan orang', 'Supaya dapat hidup bersama dengan aman dan hormat', 'D', 'Fikirkan kehidupan bersama dalam masyarakat.', 'Mengenali agama dan kepercayaan lain membantu rakyat hidup bersama dengan aman dan hormat.'),
(506, 5, 'Antara berikut, yang manakah BUKAN agama dalam senarai tujuh agama dan ajaran?', 'Hindu', 'Buddha', 'Magavau', 'Kristian', 'C', 'Satu nama ialah upacara kaum.', 'Magavau ialah upacara Kadazandusun, bukan agama dalam senarai tujuh agama dan ajaran.'),
(507, 5, 'Kenny dalam cerita mewakili ajaran apakah?', 'Ajaran Hindu dan Ajaran Sikh', 'Ajaran Buddha dan Kristian', 'Ajaran Islam dan Ajaran Sikh', 'Ajaran Tao dan Ajaran Konfusius', 'D', 'Dua ajaran, satu wakil.', 'Kenny mewakili Ajaran Tao dan Ajaran Konfusius.'),
(508, 5, 'Apakah rumah ibadat bagi penganut Islam?', 'Gereja', 'Masjid', 'Kuil', 'Gurdwara', 'B', 'Rumah ibadat dengan kubah dan menara.', 'Rumah ibadat penganut Islam ialah masjid.'),
(509, 5, 'Apakah rumah ibadat bagi penganut Kristian?', 'Gereja', 'Masjid', 'Gurdwara', 'Wat', 'A', 'Bangunan dengan menara dan salib.', 'Rumah ibadat penganut Kristian ialah gereja.'),
(510, 5, 'Apakah rumah ibadat bagi penganut Hindu?', 'Tokong', 'Gereja', 'Kuil', 'Masjid', 'C', 'Menara berwarna-warni.', 'Rumah ibadat penganut Hindu ialah kuil.'),
(511, 5, 'Apakah rumah ibadat bagi penganut Sikh?', 'Kuil lama', 'Tokong lama', 'Wat lama', 'Gurdwara', 'D', 'Bangunan putih dengan kubah emas.', 'Rumah ibadat penganut Sikh ialah gurdwara.'),
(512, 5, 'Apakah rumah ibadat bagi penganut Buddha?', 'Masjid atau kuil', 'Gereja atau gurdwara', 'Tokong atau wat', 'Kuil atau gereja', 'C', 'Ada dua nama yang digunakan.', 'Rumah ibadat penganut Buddha ialah tokong atau wat.'),
(513, 5, 'Apakah rumah ibadat bagi penganut Ajaran Konfusius dan Ajaran Tao?', 'Kuil', 'Gurdwara', 'Gereja', 'Tokong', 'D', 'Nama yang sama dengan salah satu rumah ibadat Buddha.', 'Rumah ibadat penganut Ajaran Konfusius dan Ajaran Tao ialah tokong.'),
(514, 5, 'Penganut manakah menggunakan gurdwara sebagai rumah ibadat?', 'Hindu', 'Kristian', 'Sikh', 'Buddha', 'C', 'Rumah ibadat dengan kubah emas.', 'Gurdwara ialah rumah ibadat penganut Sikh.'),
(515, 5, 'Rumah ibadat manakah dikongsi namanya oleh Buddha, Konfusius dan Tao?', 'Tokong', 'Gurdwara', 'Gereja', 'Masjid', 'A', 'Satu nama untuk tiga kumpulan.', 'Tokong digunakan oleh penganut Buddha, Ajaran Konfusius dan Ajaran Tao.'),
(516, 5, 'Apakah agama bagi Persekutuan menurut Perkara 3(1) Perlembagaan?', 'Kristian', 'Buddha', 'Islam', 'Hindu', 'C', 'Perkara 3(1) membuka bahagian ini.', 'Perkara 3(1) menyatakan Islam adalah agama bagi Persekutuan.'),
(517, 5, 'Apakah yang dinyatakan tentang agama lain dalam Perkara 3(1)?', 'Boleh diamalkan dengan aman dan damai', 'Dilarang diamalkan di Persekutuan', 'Hanya boleh diamalkan di rumah sendiri', 'Hanya boleh diamalkan di kawasan pedalaman', 'A', 'Perkara 3(1) memberi jaminan kepada agama lain.', 'Perkara 3(1) menyatakan agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.'),
(518, 5, 'Siapakah Ketua Agama Islam di negeri yang mempunyai Raja, menurut Perkara 3(2)?', 'Raja negeri itu', 'Yang di-Pertua Negeri', 'Perdana Menteri', 'Menteri Besar', 'A', 'Gelaran bergantung kepada jenis negeri.', 'Perkara 3(2) menyatakan Raja ialah Ketua Agama Islam di negeri beraja.'),
(519, 5, 'Di manakah Yang di-Pertuan Agong menjadi Ketua Agama Islam menurut Perkara 3(3)?', 'Selangor, Perak, Kedah dan Johor', 'Melaka, Pulau Pinang, Sabah dan Sarawak', 'Perlis, Kelantan, Pahang dan Terengganu', 'Kuala Lumpur, Labuan dan Putrajaya sahaja', 'B', 'Empat negeri tanpa Raja.', 'Perkara 3(3) menyatakan Yang di-Pertuan Agong ialah Ketua Agama Islam di Melaka, Pulau Pinang, Sabah dan Sarawak.'),
(520, 5, 'Siapakah Ketua Agama Islam Wilayah Persekutuan menurut Perkara 3(5)?', 'Sultan Selangor', 'Yang di-Pertuan Agong', 'Yang di-Pertua Negeri', 'Menteri Besar', 'B', 'Perkara 3(5) menyebut tiga wilayah.', 'Perkara 3(5) menyatakan Yang di-Pertuan Agong ialah Ketua Agama Islam Wilayah Persekutuan.'),
(521, 5, 'Manakah tiga Wilayah Persekutuan yang disebut dalam Perkara 3(5)?', 'Kuala Lumpur, Melaka dan Putrajaya', 'Labuan, Kuching dan Putrajaya', 'Kuala Lumpur, Labuan dan Putrajaya', 'Kuala Lumpur, Johor Bahru dan Labuan', 'C', 'Ingat ibu kota, pulau dan pusat pentadbiran.', 'Perkara 3(5) menyebut Wilayah Persekutuan Kuala Lumpur, Labuan dan Putrajaya.'),
(522, 5, 'Perkara manakah menyatakan kedudukan Raja sebagai Ketua Agama Islam di negeri beraja?', 'Perkara 3(1)', 'Perkara 3(3)', 'Perkara 3(5)', 'Perkara 3(2)', 'D', 'Perkara kedua dalam bahagian ini.', 'Perkara 3(2) menyatakan kedudukan Raja sebagai Ketua Agama Islam di negeri beraja.'),
(523, 5, 'Mengapakah Yang di-Pertuan Agong menjadi Ketua Agama Islam di Sabah?', 'Sabah mempunyai banyak Raja', 'Sabah tidak mempunyai agama', 'Sabah baru menyertai Persekutuan', 'Sabah tidak mempunyai Raja', 'D', 'Perkara 3(3) berkait dengan negeri tanpa Raja.', 'Perkara 3(3) meletakkan Yang di-Pertuan Agong sebagai Ketua Agama Islam di negeri tanpa Raja seperti Sabah.'),
(524, 5, 'Mengapakah Perkara 3(1) penting kepada rakyat berbilang agama?', 'Melarang semua agama lain di Persekutuan ini', 'Menjamin agama lain diamalkan dengan aman dan damai', 'Hanya menyebut agama Islam tanpa jaminan lain', 'Memisahkan rakyat mengikut agama dan kaum mereka', 'B', 'Fikirkan kebebasan beragama.', 'Perkara 3(1) menjadikan Islam agama Persekutuan sambil menjamin agama lain diamalkan dengan aman dan damai.'),
(525, 5, 'Suku manakah mengadakan upacara Puja Pantai?', 'Suku Mah Meri', 'Suku Temiar', 'Suku Semai', 'Suku Bajau', 'A', 'Upacara itu di tepi laut.', 'Suku Mah Meri mengadakan upacara Puja Pantai.'),
(526, 5, 'Apakah tujuan upacara Puja Pantai suku Mah Meri?', 'Menghalau kuasa jahat daripada badan orang yang sakit', 'Meraikan tuaian padi di sawah yang luas', 'Memohon perlindungan dan pengampunan daripada semangat laut', 'Menjamu tetamu selepas kematian sebagai sedekah', 'C', 'Berkait dengan laut.', 'Puja Pantai diadakan untuk perlindungan dan pengampunan daripada semangat laut.'),
(527, 5, 'Apakah yang dipercayai oleh Orang Asli sebagai punca penyakit?', 'Kuasa jahat', 'Semangat padi', 'Petara', 'Kinorohingan', 'A', 'Berkait dengan upacara menghalau.', 'Orang Asli percaya penyakit disebabkan kuasa jahat.'),
(528, 5, 'Suku manakah mengadakan upacara ritual untuk menghalau kuasa jahat?', 'Temiar dan Semai', 'Mah Meri dan Iban', 'Bajau dan Bisaya', 'Kadazandusun dan Iban', 'A', 'Dua suku di Semenanjung.', 'Suku Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat.'),
(529, 5, 'Antara berikut, yang manakah upacara suku Mah Meri?', 'Upacara Miring', 'Upacara Magavau', 'Upacara Tamarok', 'Puja Pantai', 'D', 'Pilih upacara Orang Asli.', 'Puja Pantai ialah upacara suku Mah Meri.'),
(530, 5, 'Suku Orang Asli manakah yang percaya semangat laut?', 'Iban', 'Mah Meri', 'Bajau', 'Kadazandusun', 'B', 'Orang Asli Semenanjung di tepi laut.', 'Suku Mah Meri mengadakan Puja Pantai untuk semangat laut.'),
(531, 5, 'Mengapakah Orang Asli mengadakan upacara ritual apabila ada yang sakit?', 'Untuk memuja semangat padi di sawah yang luas lagi subur', 'Untuk menjamu tetamu sebagai sedekah selepas kematian di kampung', 'Untuk membuka kawasan pertanian baharu di tepi hutan belantara', 'Untuk menghalau kuasa jahat yang dipercayai menyebabkan penyakit', 'D', 'Hubungan antara penyakit dan kepercayaan.', 'Orang Asli percaya penyakit disebabkan kuasa jahat, lalu mengadakan ritual untuk menghalaunya.'),
(532, 5, 'Siapakah Petara dalam kepercayaan Iban?', 'Penyair', 'Ketua bomoh', 'Penjaga padi', 'Dewa', 'D', 'Dewa yang dipuja.', 'Petara ialah dewa dalam kepercayaan masyarakat Iban.'),
(533, 5, 'Bagaimanakah Petara menyampaikan petanda dan alamat kepada masyarakat Iban?', 'Melalui mimpi dan bayangan', 'Melalui bunyi ombak di laut', 'Melalui asap kemenyan tebal', 'Melalui pokok besar di tebing', 'A', 'Dua cara yang berlaku semasa tidur dan siang.', 'Petara menyampaikan petanda dan alamat melalui mimpi dan bayangan.'),
(534, 5, 'Apakah upacara untuk memuja Petara?', 'Miring', 'Magavau', 'Puja Pantai', 'Tamarok', 'A', 'Upacara Iban.', 'Petara dipuja melalui beberapa upacara seperti upacara Miring.'),
(535, 5, 'Dengan apakah upacara Miring dimulakan?', 'Tarian ngajat', 'Jampi mentera', 'Jamuan sedekah', 'Tiupan sape', 'B', 'Bacaan khas.', 'Upacara Miring dimulai dengan jampi mentera.'),
(536, 5, 'Siapakah yang melakukan upacara Miring?', 'Bobohizan', 'Tok Batin', 'Imam', 'Lemambang', 'D', 'Seorang penyair.', 'Upacara Miring dilakukan oleh seorang penyair dikenali sebagai Lemambang.'),
(537, 5, 'Siapakah Kinorohingan dalam kepercayaan Kadazandusun?', 'Dewa penyampai petanda dan alamat', 'Semangat laut yang dipercayai', 'Tuhan untuk meminta sesuatu', 'Penyair yang memimpin upacara', 'C', 'Dimohon apabila ada hajat.', 'Kinorohingan ialah Tuhan untuk meminta sesuatu bagi masyarakat Kadazandusun.'),
(538, 5, 'Apakah semangat yang dipercayai oleh masyarakat Kadazandusun?', 'Semangat laut', 'Semangat hutan Temiar', 'Semangat padi', 'Semangat Petara', 'C', 'Berkait dengan tanaman.', 'Masyarakat Kadazandusun percaya semangat padi dan menjalankan upacara Magavau.'),
(539, 5, 'Apakah upacara Kadazandusun untuk semangat padi?', 'Miring', 'Magavau', 'Tamarok', 'Ngeduang', 'B', 'Upacara Kadazandusun.', 'Upacara Magavau dijalankan untuk semangat padi.'),
(540, 5, 'Siapakah yang mengetuai upacara Magavau?', 'Lemambang', 'Bobohizan', 'Petara', 'Tok Batin', 'B', 'Ketua bomoh.', 'Upacara Magavau diketuai oleh ketua bomoh dikenali sebagai Bobohizan.'),
(541, 5, 'Apakah perbezaan Lemambang Iban dengan Bobohizan Kadazandusun?', 'Lemambang melakukan Miring, Bobohizan mengetuai Magavau', 'Lemambang mengetuai Magavau, Bobohizan melakukan Miring', 'Kedua-duanya menjalankan upacara Tamarok', 'Kedua-duanya memimpin upacara Puja Pantai', 'A', 'Setiap tokoh milik kaum dan upacara sendiri.', 'Lemambang melakukan upacara Miring (Iban), manakala Bobohizan mengetuai Magavau (Kadazandusun).'),
(542, 5, 'Apakah pekerjaan masyarakat Bisaya di Sarawak yang disebut dalam kepercayaan mereka?', 'Nelayan', 'Pelombong', 'Petani', 'Pedagang', 'C', 'Berkait dengan kawasan pertanian.', 'Masyarakat Bisaya di Sarawak bekerja sebagai petani dan mempercayai kuasa ghaib.'),
(543, 5, 'Mengapakah masyarakat Bisaya membaca jampi mentera sebelum membuka kawasan pertanian baharu?', 'Untuk meraikan tuaian', 'Untuk menjamu tetamu', 'Untuk menghormati warisan', 'Untuk mengelakkan gangguan', 'D', 'Jampi dibaca demi keselamatan.', 'Jampi mentera dibaca untuk mengelakkan gangguan semasa membuka kawasan pertanian baharu.'),
(544, 5, 'Apakah upacara Bisaya untuk menghalau kuasa ghaib daripada badan pesakit?', 'Miring', 'Tamarok', 'Ngeduang', 'Magavau', 'B', 'Upacara untuk pesakit.', 'Upacara Tamarok dilaksanakan bagi menghalau kuasa ghaib daripada badan pesakit.'),
(545, 5, 'Apakah upacara Bajau yang diamalkan di Kota Belud?', 'Mag''ombo', 'Tamarok', 'Ngeduang', 'Miring', 'C', 'Pantai barat Sabah.', 'Upacara Ngeduang diamalkan di pantai barat Sabah, Kota Belud.'),
(546, 5, 'Apakah yang dilakukan oleh keluarga si mati dalam upacara Ngeduang?', 'Menghalau kuasa ghaib daripada badan pesakit', 'Menjamu makanan kepada tetamu sebagai sedekah', 'Menghargai warisan di tepi pantai timur', 'Membacakan jampi mentera di tengah ladang', 'B', 'Berkait dengan makanan dan tetamu.', 'Dalam Ngeduang, keluarga si mati menjamu makanan kepada tetamu sebagai sedekah.'),
(547, 5, 'Di manakah upacara Mag''ombo diadakan?', 'Kota Belud, pantai barat Sabah', 'Semporna, pantai timur Sabah', 'Tambunan, pedalaman Sabah', 'Kuching, bandar Sarawak', 'B', 'Pantai timur Sabah.', 'Etnik Bajau di pantai timur, Semporna, mengadakan upacara Mag''ombo.'),
(548, 5, 'Apakah maksud Mag''ombo?', 'Menjamu tetamu sebagai sedekah selepas kematian di Kota Belud', 'Menghalau kuasa ghaib daripada badan pesakit di ladang baharu', 'Menghargai dan menghormati warisan agar kehidupan dirahmati', 'Membaca jampi mentera sebelum membuka kawasan pertanian baharu', 'C', 'Berkait dengan warisan.', 'Mag''ombo bermaksud menghargai dan menghormati warisan turun-temurun agar kehidupan dirahmati.'),
(549, 5, 'Apakah perbezaan Ngeduang dengan Mag''ombo?', 'Ngeduang di Kota Belud, Mag''ombo di Semporna', 'Ngeduang di Semporna, Mag''ombo di Kota Belud', 'Kedua-duanya di Kota Belud sahaja', 'Kedua-duanya di Semporna sahaja', 'A', 'Pantai barat dan pantai timur.', 'Ngeduang diamalkan di pantai barat (Kota Belud), manakala Mag''ombo di pantai timur (Semporna).'),
(550, 5, 'Antara berikut, yang manakah dikaitkan dengan masyarakat Bisaya di Sarawak?', 'Ngeduang', 'Tamarok', 'Mag''ombo', 'Magavau', 'B', 'Upacara untuk pesakit.', 'Tamarok ialah upacara masyarakat Bisaya bagi menghalau kuasa ghaib daripada badan pesakit.');
